# Instructions ----
#' This file follows the format generated by FIMS:::use_testthat_template().
#' Necessary tests include input and output (IO) correctness [IO
#' correctness], edge-case handling [Edge handling], and built-in errors and
#' warnings [Error handling]. See `?FIMS:::use_testthat_template` for more
#' information. Every test should have a @description tag, which can only span
#' one lines, that will be used in the bookdown report of the results from
#' {testthat}. This line can be more than 80 characters.

# strict_list ----
## Setup ----
# Parameters grouped by module and fleet, as the model reads them.
module_parameters <- FIMS:::strict_list(list(
  Selectivity = list(fleet1 = list(inflection_point = 2, slope = 1)),
  Population = list(log_M = log(0.2), log_init_naa = log(c(100, 50, 25)))
))
data("data_big")
data_4_model <- FIMSFrame(data_big)
default_parameters <- setup_default_parameters(data = data_4_model)

## IO correctness ----
test_that("`strict_list()` works with correct inputs", {
  #' @description Test that `strict_list()` reads an element by its name with `[[`.
  expect_equal(
    object = module_parameters[["Population"]][["log_M"]],
    expected = log(0.2)
  )
  #' @description Test that `strict_list()` reads an element by its full name with `$`.
  expect_equal(
    object = module_parameters$Selectivity$fleet1$slope,
    expected = 1
  )
  #' @description Test that `strict_list()` reads an element by its number as a plain list does.
  expect_equal(
    object = module_parameters[[2]][[2]],
    expected = log(c(100, 50, 25))
  )
  #' @description Test that `strict_list()` makes each list inside it strict too.
  expect_s3_class(
    object = module_parameters[["Selectivity"]][["fleet1"]],
    class = "strict_list"
  )
})

## Edge handling ----
test_that("`strict_list()` returns correct outputs for edge cases", {
  # An element can be there with the value NULL, as the length bins of a fleet
  # without length data are.
  fleet_data <- FIMS:::strict_list(list(length_bins = NULL, has_catch = TRUE))
  #' @description Test that `strict_list()` returns NULL for a name that is there with the value NULL.
  expect_null(fleet_data[["length_bins"]])
  #' @description Test that `strict_list()` keeps the class of a data frame inside it.
  expect_s3_class(
    object = FIMS:::strict_list(list(rows = data.frame(age = 1:3)))[["rows"]],
    class = "data.frame",
    exact = TRUE
  )
  #' @description Test that `$` on a strict list does not match the start of a longer name, as it would on a plain list.
  expect_error(
    object = module_parameters$Selectivity$fleet1$slo,
    regexp = "named .slo."
  )
})

## Error handling ----
test_that("`strict_list()` returns correct error messages", {
  #' @description Test that `[[` on a strict list stops on a misspelled name and names it.
  expect_error(
    object = module_parameters[["Population"]][["log_m"]],
    regexp = "named .log_m."
  )
  #' @description Test that `[[` on a strict list lists the names it has when it stops.
  expect_error(
    object = module_parameters[["Population"]][["log_m"]],
    regexp = "The names in this list are .log_M. and .log_init_naa."
  )
  # The likelihoods in the model data are a list with no names.
  likelihoods <- FIMS:::strict_list(list(list(name = "fleet1_catch")))
  #' @description Test that `[[` on a strict list with no names says that it is read by position.
  expect_error(
    object = likelihoods[["fleet1_catch"]],
    regexp = "no names, so it is read by position"
  )
  #' @description Test that `$` on a strict list stops on a misspelled name and names it.
  expect_error(
    object = module_parameters$Population$log_m,
    regexp = "named .log_m."
  )
  #' @description Test that a nested lookup stops at a misspelled fleet, the inner level.
  expect_error(
    object = module_parameters[["Selectivity"]][["fleet2"]][["slope"]],
    regexp = "named .fleet2."
  )
  #' @description Test that a nested lookup stops at a misspelled label, the innermost level.
  expect_error(
    object = module_parameters[["Selectivity"]][["fleet1"]][["slop"]],
    regexp = "named .slop."
  )
})

test_that("`strict_list()` stops a fit when model code misspells a name", {
  input <- initialize_fims(default_parameters, data = data_4_model)
  original_population_biology <- FIMS:::population_biology
  # The mock reads "log_m" for "log_M". A plain list would give NULL, and
  # exp(sum(NULL)) is 1, so the fit would run on with no error.
  local_mocked_bindings(
    population_biology = function(module_parameters, model_data,
                                  population_data) {
      biology <- original_population_biology(
        module_parameters, model_data, population_data
      )
      biology[["mortality_M"]] <- biology[["mortality_M"]] *
        exp(sum(module_parameters[["Population"]][["log_m"]]))
      biology
    }
  )
  #' @description Test that `fit_fims()` stops with the strict-list error when model code reads a misspelled parameter name.
  expect_error(
    object = fit_fims(input, optimize = FALSE),
    regexp = "named .log_m."
  )
})
